class Solution {
public:
    int scoreOfString(string s) {
        int score = 0;
        int n = (int)s.size();
        for (int i = 1; i < n; i++) {
            int diff = s[i] - s[i - 1];
            if (diff < 0) diff = -diff;
            score += diff;
        }
        return score;
    }
};
